import json
from collections import deque

def handler(input_data):
    start_x = int(input_data['start_x'])
    start_y = int(input_data['start_y'])
    target_x = int(input_data['target_x'])
    target_y = int(input_data['target_y'])
    map_id = input_data['map_id']

    # Generate verified passable tiles
    passable = set()

    if map_id == '0_82':  # 1F
        # 1. Entrance Area (Columns 14-17, Rows 2-7)
        for x in range(14, 18):
            for y in range(2, 8):
                passable.add((x, y))
        # 2. Chamber 1 connector (Columns 14-28, Row 7)
        for x in range(14, 29):
            passable.add((x, 7))
        # 3. Pokemaniac area (Column 22, Rows 8-12; Column 23, Row 12)
        for y in range(8, 13):
            passable.add((22, y))
        passable.add((23, 12))
        # 4. Eastern corridor (Columns 20-33, Rows 11-13)
        for x in range(20, 34):
            for y in range(11, 14):
                passable.add((x, y))
        # 5. Columns 34-37, Rows 8-12
        for x in range(34, 38):
            for y in range(8, 13):
                passable.add((x, y))
        # 6. Ladder A area (Columns 34-37, Rows 2-7)
        for x in range(34, 38):
            for y in range(2, 8):
                passable.add((x, y))
        # 7. New Section - Ladder B1F area (Columns 4-7, Rows 2-7)
        for x in range(4, 8):
            for y in range(2, 8):
                passable.add((x, y))
        # 8. Left corridor of new section (Columns 2-5, Rows 7-21)
        for x in range(2, 6):
            for y in range(7, 22):
                passable.add((x, y))
        # 9. Connecting bottom section (Columns 2-21, Rows 16-21)
        for x in range(2, 22):
            for y in range(16, 22):
                passable.add((x, y))
        # 10. Open space / Eastern new section (Columns 10-21, Rows 14-15)
        for x in range(10, 22):
            for y in range(14, 16):
                passable.add((x, y))

    elif map_id == '0_232':  # B1F
        # 1. Starting Chamber (Columns 28-37, Rows 21-29)
        for x in range(28, 38):
            for y in range(21, 30):
                passable.add((x, y))
        # 2. Row 31 bypass & South area (Columns 17-29, Row 31)
        for x in range(17, 30):
            passable.add((x, 31))
        # 3. South corridor (Columns 28-29, Row 30)
        passable.add((28, 30))
        passable.add((29, 30))
        # 4. Left vertical corridor (Column 17, Rows 27-31)
        for y in range(27, 32):
            passable.add((17, y))
        # 5. Upper East-West corridor (Columns 17-25, Rows 22-27)
        for x in range(17, 26):
            for y in range(22, 28):
                passable.add((x, y))
        # 6. Row 18 & 19 Upper Bypass Connection (Columns 20-29, Rows 18-20)
        for x in range(20, 30):
            for y in range(18, 21):
                passable.add((x, y))
        # 7. Northern Corridor (Columns 29-37, Rows 1-5)
        for x in range(29, 38):
            for y in range(1, 6):
                passable.add((x, y))
        # 8. Ladder A at (33, 25)
        passable.add((33, 25))
        # 9. Ladder B at (27, 3)
        passable.add((27, 3))
        # 10. Column 36-37 vertical corridor (Columns 36-37, Rows 6-20)
        for x in range(36, 38):
            for y in range(6, 21):
                passable.add((x, y))
        # 11. Row 19 horizontal connector (Columns 30-35, Rows 18-20)
        for x in range(30, 36):
            for y in range(18, 21):
                passable.add((x, y))

    # Add start and target to passable just in case
    passable.add((start_x, start_y))
    passable.add((target_x, target_y))

    # BFS pathfinder
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    directions = [
        ('Up', 0, -1),
        ('Down', 0, 1),
        ('Left', -1, 0),
        ('Right', 1, 0)
    ]

    found_path = None
    while queue:
        cx, cy, path = queue.popleft()
        if cx == target_x and cy == target_y:
            found_path = path
            break

        for btn, dx, dy in directions:
            nx, ny = cx + dx, cy + dy
            if (nx, ny) in passable and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, path + [btn]))

    if found_path is None:
        return json.dumps([])
    else:
        return json.dumps(found_path)
